 private static CombatPoisonLifecycle.State state(BattleTimedStatus t,boolean poison,boolean create){return poison?CombatPoisonLifecycle.monsterPoisonCallbacks(t,create):CombatPoisonLifecycle.monsterCallbacks(t,create);}
