 static BattleTimedStatus.MagicCancellation magicResult(BattleTimedStatus.MagicCancellation a,boolean repeated){if(!repeated)return a;return new BattleTimedStatus.MagicCancellation(a.haste(),a.slow(),a.brave(),a.blind(),a.weakness(),a.disease(),a.silence(),a.decayPotion(),a.polluteWater(),a.strikerGale(),a.light(),a.bluePotion(),a.wisdomPotion(),a.meditation(),a.concentration(),a.counterMagic(),a.breath(),false,a.sleep(),a.freeze(),a.earthBind(),a.burningSpirit(),a.elementalFire(),a.soulOfFlame(),a.venomResist(),a.doubleBrake(),a.horrorOfDeath(),a.thunderGrab(),a.boneBreak(),a.paralysisCancellation());}
