 static boolean damageActive(BattleTimedStatus t,long now){synchronized(t){var s=state(t,true,false);var c=s==null?null:owner(s.current());return CombatRules.loaded()&&c!=null&&c.damage!=null?number(t,"poisonExpiresAtNanos")!=0:t.poisonActive(now);}}
 static BattleTimedStatus.PoisonPoll damagePoll(BattleTimedStatus t,long now,int interval){synchronized(t){var s=state(t,true,false);var c=s==null?null:owner(s.current());return CombatRules.loaded()&&c!=null&&c.damage!=null?new BattleTimedStatus.PoisonPoll(0,false):t.pollPoison(now,interval);}}
 static boolean cureDamage(BattleTimedStatus t){synchronized(t){var s=state(t,true,false);var c=s==null?null:owner(s.current());return CombatRules.loaded()&&c!=null&&c.damage!=null?cancel(t,true).present():t.curePoison();}}
 private static Curse paralysisOwner(BattleTimedStatus t){var s=state(t,true,false);var c=s==null?null:owner(s.current());return CombatRules.loaded()&&c!=null&&c.paralysis!=null?c:null;}
 static boolean managedPoisonParalysis(BattleTimedStatus t){synchronized(t){return paralysisOwner(t)!=null;}}
 static boolean poisonParalysisVisual(BattleTimedStatus t){synchronized(t){var c=paralysisOwner(t);return c!=null&&c.phase!=0&&number(t,"paralysisActivatesAtNanos")!=0;}}
