 static boolean visual(BattleTimedStatus t,BattleTimedStatus slot,long now){synchronized(t){var c=current(t);return c!=null&&c.slot==slot?c.phase!=0:slot.paralysisVisualActive(now);}}
 static boolean active(BattleTimedStatus t,BattleTimedStatus slot,long now){synchronized(t){var c=current(t);return c!=null&&c.slot==slot?c.phase==ACTIVE:slot.paralysisActive(now);}}
 static BattleTimedStatus.ParalysisCancellation cancel(BattleTimedStatus t){return cancel(t,false);}
 private static BattleTimedStatus.ParalysisCancellation cancel(BattleTimedStatus t,boolean poison){synchronized(t){
  var s=state(t,poison,false);if(s==null||s.current()==null||s.current() instanceof CombatPoisonLifecycle.Transition)return new BattleTimedStatus.ParalysisCancellation(false,false);
  var c=owner(s.current());if(c==null)return new BattleTimedStatus.ParalysisCancellation(false,false);
  boolean locked=!poison&&(boolean)CombatAccess.field(c.slot,"paralysisLockEmitted");var removal=new Removal(t,c,s);c.removal=removal;
  if(!c.enter(s))throw new IllegalStateException("NPC cure lost lease");var tr=c.closeDeferred(s,removal::ready);if(tr==null){c.leave();throw new IllegalStateException("NPC cure lost transition");}removal.transition=tr;c.leave();return new BattleTimedStatus.ParalysisCancellation(true,locked);
 }}
 static boolean cureSilence(BattleTimedStatus t){synchronized(t){return CombatRules.loaded()&&poisonReserved(t)?cancel(t,true).present():t.curePoisonSilence();}}
 static void cancelPoisonMagic(BattleTimedStatus t){synchronized(t){if(CombatRules.loaded()&&poisonReserved(t)){var lease=owner(state(t,true,false).current());if(lease.removal==null||!lease.removal.ready){if(lease.paralysis!=null){if(lease.phase!=0)paralysisMarkers(t,lease.phase==ACTIVE);else clear(t);}else if(lease.damage==null)CombatAccess.set(t,"poisonSilence",true);else{CombatAccess.set(t,"poisonExpiresAtNanos",lease.damage.expires);CombatAccess.set(t,"poisonNextTickAtNanos",lease.damage.next);}}cancel(t,true);}}}
 private static void nativeClear(ClassicWorldMonsterPopulation population,Object actor){CombatAccess.call(population,"clearPoisonSource","(L"+P+"ClassicWorldMonsterPopulation$Actor;)V",actor);}
 static void clearSource(Object actor,ClassicWorldMonsterPopulation population){synchronized(population){var t=(BattleTimedStatus)CombatAccess.field(actor,"damagePoisonStatus");synchronized(t){var s=state(t,true,false);var lease=s==null?null:owner(s.current());if(CombatRules.loaded()&&lease!=null&&lease.poison&&s.current() instanceof CombatPoisonLifecycle.Transition&&lease.epoch==CombatPoisonLifecycle.monsterEpoch(t,false)){lease.removal.attach(population,actor);return;}nativeClear(population,actor);}}}
 static void reset(BattleTimedStatus t){synchronized(t){var queue=CombatPoisonLifecycle.monsterDamage(t,false);if(CombatPoisonLifecycle.monsterCurse(t,false)==null&&!reserved(t)&&!poisonReserved(t)&&queue==null)return;CombatPoisonLifecycle.monsterEpoch(t,true);if(queue!=null)queue.clear(false);if(reserved(t))cancel(t);if(poisonReserved(t)){var lease=owner(state(t,true,false).current());cancel(t,true);CombatAccess.set(t,"poisonSilence",false);CombatAccess.set(t,"poisonExpiresAtNanos",0L);CombatAccess.set(t,"poisonNextTickAtNanos",0L);if(lease.paralysis!=null){clear(t);lease.phase=0;}}CombatPoisonLifecycle.discardMonsterCurse(t);}}
 private static void activateCallback(BattleTimedStatus t,Curse lease,long now){var s=state(t,false);if(s==null||!lease.enter(s))return;try{if(s.isCurrent(lease)&&lease.phase==WAITING){long wall=System.nanoTime(),anchor=Math.max(now,wall);lease.phase=ACTIVE;CombatAccess.set(lease.slot,"paralysisActivatesAtNanos",anchor);CombatAccess.set(lease.slot,"paralysisExpiresAtNanos",Long.MAX_VALUE);CombatAccess.set(lease.slot,"paralysisLockEmitted",true);CombatAccess.set(lease.slot,"paralysisExpiresAtNanos",Math.addExact(Math.addExact(anchor,Math.max(0,System.nanoTime()-wall)),lease.duration));}}finally{lease.leave();}}
 static BattleTimedStatus.ParalysisPoll poll(BattleTimedStatus t,BattleTimedStatus slot,long now){synchronized(t){var s=state(t,false);var c=s==null?null:owner(s.current());if(c==null||c.slot!=slot)return slot.pollParalysis(now);if(s.current() instanceof CombatPoisonLifecycle.Transition||c.phase==INITIAL)return new BattleTimedStatus.ParalysisPoll(false,false,false);if(c.phase==WAITING&&now>=number(slot,"paralysisActivatesAtNanos")){activateCallback(t,c,now);return new BattleTimedStatus.ParalysisPoll(false,false,false);}if(c.phase==ACTIVE&&now>=number(slot,"paralysisExpiresAtNanos")){cancel(t);return new BattleTimedStatus.ParalysisPoll(false,true,false);}return new BattleTimedStatus.ParalysisPoll(false,false,false);}}
 static Actor actor(GameHub hub,int map,int instance,long id){var pop=(ClassicWorldMonsterPopulation)CombatAccess.call(hub,"classicWorldMonsterPopulation","(II)L"+P+"ClassicWorldMonsterPopulation;",map,instance);if(pop==null)return null;synchronized(pop){var a=((Map<?,?>)CombatAccess.field(pop,"actors")).get(id);if(a==null)return null;return new Actor(pop,a,(BattleTimedStatus)CombatAccess.field(a,"damagePoisonStatus"),id,map,instance,hub);}}
